import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ProjectGrid from './components/ProjectGrid';
import ProjectModal from './components/ProjectModal';
import SecurityOverlay from './components/SecurityOverlay';
import Footer from './components/Footer';
import { Project } from './types';

const App: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Security layer: Disable right-click, inspection shortcuts, and text selection
  useEffect(() => {
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeyDown = (e: KeyboardEvent) => {
      // Disable Ctrl+U, Ctrl+Shift+I, Ctrl+Shift+J, Ctrl+S
      if (
        (e.ctrlKey && (e.key === 'u' || e.key === 's')) ||
        (e.ctrlKey && e.shiftKey && (e.key === 'I' || e.key === 'J' || e.key === 'C')) ||
        e.key === 'F12'
      ) {
        e.preventDefault();
      }
    };

    window.addEventListener('contextmenu', handleContextMenu);
    window.addEventListener('keydown', handleKeyDown);

    // Initial load simulation for cinematic feel
    const timer = setTimeout(() => setIsLoading(false), 1500);

    return () => {
      window.removeEventListener('contextmenu', handleContextMenu);
      window.removeEventListener('keydown', handleKeyDown);
      clearTimeout(timer);
    };
  }, []);

  return (
    <div className="relative min-h-screen bg-onyx selection:bg-transparent">
      <div className="noise-bg absolute inset-0 z-0"></div>

      <AnimatePresence>
        {isLoading && (
          <motion.div 
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-onyx flex items-center justify-center"
          >
            <motion.div 
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className="text-gold-500 font-serif text-4xl italic tracking-widest"
            >
              CHRONOS
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <Navbar />

      <main className="relative z-10">
        <Hero />
        <ProjectGrid onProjectSelect={setSelectedProject} />
      </main>

      <Footer />

      <AnimatePresence>
        {selectedProject && (
          <ProjectModal 
            project={selectedProject} 
            onClose={() => setSelectedProject(null)} 
          />
        )}
      </AnimatePresence>

      <SecurityOverlay />
    </div>
  );
};

export default App;

