import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Project, Message } from '../types';
import { BarChart, Bar, ResponsiveContainer, XAxis, YAxis, Tooltip, Cell } from 'recharts';

interface DemoRendererProps {
  project: Project;
}

const DemoRenderer: React.FC<DemoRendererProps> = ({ project }) => {
  if (project.demoType === 'GEMINI') {
    return <AIDemo />;
  }
  if (project.demoType === 'VISUALIZER') {
    return <DataDemo />;
  }
  return <InteractiveCanvasDemo />;
};

const AIDemo: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Neural Nexus online. Awaiting strategic query sequence...' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMsg: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      // For the demo, we use a controlled "Client Portfolio AI" personality
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: input,
        config: {
          systemInstruction: 'You are the Neural Nexus AI, a sophisticated agent within a cinematic portfolio. Answer queries about technology, AI, and design with a professional, futuristic, and concise tone. Mention that you are part of a high-end portfolio demo.',
          maxOutputTokens: 200,
        }
      });

      const modelMsg: Message = { role: 'model', text: response.text || "Connection lost. Re-synchronizing..." };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Critical system error. Local simulation fallback active." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-zinc-950 font-sans">
      <div ref={scrollRef} className="flex-1 p-6 overflow-y-auto space-y-6">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-sm border ${
              m.role === 'user' 
                ? 'bg-gold-500 text-black border-gold-400 font-bold' 
                : 'bg-zinc-900 text-zinc-200 border-zinc-800'
            }`}>
              <div className="text-[10px] uppercase tracking-widest mb-1 opacity-60">
                {m.role === 'user' ? 'Client' : 'Nexus'}
              </div>
              <p className="text-sm leading-relaxed">{m.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-zinc-900 p-4 rounded-sm border border-zinc-800">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-gold-500 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-gold-500 rounded-full animate-bounce delay-75"></div>
                <div className="w-1.5 h-1.5 bg-gold-500 rounded-full animate-bounce delay-150"></div>
              </div>
            </div>
          </div>
        )}
      </div>
      <div className="p-4 bg-zinc-900/50 border-t border-zinc-800">
        <div className="flex gap-2">
          <input 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Initialize query sequence..."
            className="flex-1 bg-black border border-zinc-800 rounded-sm px-4 py-2 text-sm text-white focus:outline-none focus:border-gold-500 transition-colors"
          />
          <button 
            onClick={handleSend}
            className="bg-gold-500 text-black px-6 py-2 rounded-sm font-bold text-xs uppercase hover:bg-gold-400 transition-colors"
          >
            Execute
          </button>
        </div>
      </div>
    </div>
  );
};

