const AIDemo: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Daily Bugle AI Terminal connected. Searching for relevant intel...' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMsg: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: input,
        config: {
          systemInstruction: 'You are the Daily Bugle Intel Agent. Speak with a punchy, energetic, and professional journalistic tone. You are helping a high-profile client explore this portfolio.',
          maxOutputTokens: 200,
        }
      });

      const modelMsg: Message = { role: 'model', text: response.text || "Transmission interrupted by signal jamming." };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Error 404: Intel Not Found." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-black font-sans border border-white/10">
      <div ref={scrollRef} className="flex-1 p-8 overflow-y-auto space-y-8">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 ${
              m.role === 'user' 
                ? 'bg-red-marvel text-white skew-x-[-4deg]' 
                : 'bg-white text-black font-bold'
            }`}>
              <div className="text-[10px] uppercase font-black tracking-widest mb-1 opacity-50">
                {m.role === 'user' ? 'Reporter' : 'Bugle Intel'}
              </div>
              <p className="text-lg leading-tight font-impact uppercase italic">{m.text}</p>
            </div>
          </div>
        ))}
      </div>
      <div className="p-6 bg-zinc-900/80 border-t border-white/10">
        <div className="flex gap-4">
          <input 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type your headline..."
            className="flex-1 bg-black border-2 border-white/10 px-6 py-4 text-white font-impact uppercase italic focus:outline-none focus:border-red-marvel transition-colors"
          />
          <button 
            onClick={handleSend}
            className="bg-red-marvel text-white px-10 py-4 font-impact text-2xl uppercase italic hover:bg-white hover:text-black transition-all"
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
};

