import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Project, Message } from '../types';
import { BarChart, Bar, ResponsiveContainer, XAxis, YAxis, Tooltip, Cell } from 'recharts';

interface DemoRendererProps {
  project: Project;
}

const DemoRenderer: React.FC<DemoRendererProps> = ({ project }) => {
  if (project.demoType === 'GEMINI') {
    return <AIDemo />;
  }
  if (project.demoType === 'VISUALIZER') {
    return <DataDemo />;
  }
  return <InteractiveCanvasDemo />;
};

const AIDemo: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Terminal de Inteligencia Bugle conectada. Buscando información relevante...' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMsg: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: input,
        config: {
          systemInstruction: 'Eres el Agente de Inteligencia del Daily Bugle. Habla con un tono periodístico enérgico, directo y profesional. Estás ayudando a un cliente importante a explorar este portafolio.',
          maxOutputTokens: 200,
        }
      });

      const modelMsg: Message = { role: 'model', text: response.text || "Transmisión interrumpida por interferencia de señal." };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Error 404: Información no encontrada." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-black font-sans border border-white/10">
      <div ref={scrollRef} className="flex-1 p-8 overflow-y-auto space-y-8">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 ${
              m.role === 'user' 
                ? 'bg-red-marvel text-white skew-x-[-4deg]' 
                : 'bg-white text-black font-bold'
            }`}>
              <div className="text-[10px] uppercase font-black tracking-widest mb-1 opacity-50">
                {m.role === 'user' ? 'Reportero' : 'Inteligencia Bugle'}
              </div>
              <p className="text-lg leading-tight font-impact uppercase italic">{m.text}</p>
            </div>
          </div>
        ))}
      </div>
      <div className="p-6 bg-zinc-900/80 border-t border-white/10">
        <div className="flex gap-4">
          <input 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Escribe tu titular..."
            className="flex-1 bg-black border-2 border-white/10 px-6 py-4 text-white font-impact uppercase italic focus:outline-none focus:border-red-marvel transition-colors"
          />
          <button 
            onClick={handleSend}
            className="bg-red-marvel text-white px-10 py-4 font-impact text-2xl uppercase italic hover:bg-white hover:text-black transition-all"
          >
            Enviar
          </button>
        </div>
      </div>
    </div>
  );
};

