// --- PROYECTO 3: BARBERÍA (3D/INTERACTIVE) ---
const BarberDemo: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scanProgress, setScanProgress] = useState(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let points: any[] = [];
    const resize = () => {
      canvas.width = canvas.parentElement?.clientWidth || 800;
      canvas.height = canvas.parentElement?.clientHeight || 500;
    };

    const init = () => {
      resize();
      points = Array.from({ length: 80 }, () => ({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 1,
        vy: (Math.random() - 0.5) * 1
      }));
    };

    const draw = () => {
      ctx.fillStyle = 'rgba(0,0,0,0.1)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      points.forEach(p => {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
        if (p.y < 0 || p.y > canvas.height) p.vy *= -1;

        ctx.fillStyle = '#E23636';
        ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill();
      });

      points.forEach((p1, i) => {
        points.slice(i + 1).forEach(p2 => {
          const dist = Math.sqrt((p1.x - p2.x)**2 + (p1.y - p2.y)**2);
          if (dist < 120) {
            ctx.strokeStyle = `rgba(226, 54, 54, ${1 - dist/120})`;
            ctx.lineWidth = 0.5;
            ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
          }
        });
      });
      requestAnimationFrame(draw);
    };

    init(); draw();
    window.addEventListener('resize', resize);
    const interval = setInterval(() => setScanProgress(p => (p + 1) % 101), 100);
    return () => {
      window.removeEventListener('resize', resize);
      clearInterval(interval);
    };
  }, []);

  return (
    <div className="h-full relative bg-black overflow-hidden flex flex-col p-8 font-impact uppercase">
      <div className="relative z-10 mb-6">
        <h3 className="text-4xl text-white italic leading-none">ESCÁNER CRANEAL 3D</h3>
        <p className="text-red-marvel text-xs font-black">Análisis de Simetría Facial Activo</p>
      </div>

      <div className="flex-1 relative border border-white/10 group">
        <canvas ref={canvasRef} className="w-full h-full grayscale group-hover:grayscale-0 transition-all duration-700" />

        {/* HUD Elements */}
        <div className="absolute top-6 right-6 text-right">
           <p className="text-red-marvel text-5xl">{scanProgress}%</p>
           <p className="text-white text-[10px] tracking-widest font-black">PRECISIÓN DE MAPEADO</p>
        </div>
        <div className="absolute bottom-6 left-6 grid grid-cols-2 gap-4">
           {['FADE', 'TAPER', 'POMPADOUR', 'CROP'].map(style => (
             <button key={style} className="px-4 py-1 border border-white/20 text-white text-xs hover:bg-red-marvel hover:border-red-marvel transition-colors">
               SIMULAR {style}
             </button>
           ))}
        </div>

        <div className="absolute inset-0 border-[20px] border-white/5 pointer-events-none"></div>
      </div>
    </div>
  );
};

// --- PROYECTO 4: REPOSTERÍA (AI) ---
const BakeryDemo: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Laboratorio de Repostería Precisa listo. ¿Qué perfil de dulzor desea optimizar?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMsg: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: input,
        config: {
          systemInstruction: 'Eres el Maestro Pastelero Digital de la Precisión Pastelera. Responde con un tono creativo, técnico y sofisticado sobre recetas, texturas y química de los alimentos. Mantén tus respuestas breves y contundentes.',
          maxOutputTokens: 150,
        }
      });
      setMessages(prev => [...prev, { role: 'model', text: response.text || "Error en el cálculo de levaduras." }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Terminal offline. Reinicie caldera." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-black font-impact uppercase">
      <div className="bg-red-marvel text-white p-6 italic flex justify-between items-center">
        <h3 className="text-3xl tracking-tighter">ALGORITMO DE PASTELERÍA</h3>
        <span className="text-[10px] font-black tracking-widest bg-black px-2 py-1">GEN-3 ACTIVE</span>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 ${m.role === 'user' ? 'bg-white text-black' : 'bg-zinc-900 text-white border border-red-marvel/30'}`}>
              <p className="text-lg leading-tight italic">{m.text}</p>
            </div>
          </div>
        ))}
        {isTyping && <div className="text-red-marvel animate-pulse text-xs">CALCULANDO COMPONENTES QUÍMICOS...</div>}
      </div>

      <div className="p-6 bg-zinc-900 flex gap-4 border-t border-white/5">
        <input 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Ingresar variable de receta..."
          className="flex-1 bg-black border border-white/20 p-4 text-white focus:outline-none focus:border-red-marvel"
        />
        <button onClick={handleSend} className="bg-red-marvel text-white px-10 hover:bg-white hover:text-black transition-all">
          CALCULAR
        </button>
      </div>
    </div>
  );
};

