interface NavbarProps {
  onSearch: (query: string) => void;
  onViewChange: (view: ViewState) => void;
}

const Navbar: React.FC<NavbarProps> = ({ onSearch, onViewChange }) => {
  const [isSearchOpen, setIsSearchOpen] = useState(false);
