  const [searchValue, setSearchValue] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSearchToggle = () => {
    if (isSearchOpen) {
      setSearchValue('');
      onSearch('');
      setIsSearchOpen(false);
    } else {
      setIsSearchOpen(true);
    }
  };

  useEffect(() => {
    if (isSearchOpen && inputRef.current) {
